<style>
  * {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
  }
  body {
    font-family: Georgia, 'Times New Roman', serif;
    background: #ccc;
    display: flex;
    justify-content: center;
    padding: 20px 0;
  }
  .cover {
    width: 465px;
    height: 690px;
    background: linear-gradient(135deg, #eef0f5 0%, #dfe3ee 40%, #e8eaf0 60%, #dcdfe9 100%);
    position: relative;
    display: flex;
    box-shadow: 0 0 10px rgba(0,0,0,0.3);
    overflow: hidden;
  }

  /* Left sidebar */
  .sidebar {
    width: 78px;
    background: linear-gradient(180deg, #2b3f8c 0%, #1e2f6e 100%);
    display: flex;
    flex-direction: column;
    align-items: center;
    position: relative;
    flex-shrink: 0;
  }
  .stripe {
    width: 6px;
    background: #f5a623;
    height: 100%;
    position: absolute;
    left: 78px;
    top: 0;
  }
  .elsevier-logo-box {
    background: #fff;
    width: 56px;
    height: 56px;
    margin-top: 18px;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .elsevier-logo-box svg {
    width: 34px;
    height: 34px;
  }
  .elsevier-text {
    color: #fff;
    font-size: 10px;
    letter-spacing: 1px;
    margin-top: 6px;
    font-weight: bold;
    font-family: Arial, sans-serif;
  }

  .earli-block {
    margin-top: auto;
    margin-bottom: 14px;
    padding: 0 6px;
    text-align: center;
  }
  .earli-logo {
    color: #f5a623;
    font-size: 20px;
    font-weight: bold;
    font-style: italic;
    font-family: Georgia, serif;
  }
  .earli-caption {
    color: #dfe3f0;
    font-size: 7px;
    line-height: 1.3;
    margin-top: 6px;
    font-family: Arial, sans-serif;
  }

  /* Main content area */
  .content {
    flex: 1;
    position: relative;
    padding: 20px 28px 20px 22px;
  }

  .top-bar {
    display: flex;
    justify-content: flex-end;
    gap: 30px;
    font-family: Arial, sans-serif;
    font-size: 11px;
    color: #2b3f8c;
    font-weight: bold;
    margin-bottom: 30px;
    margin-top: 4px;
  }

  .globe-graphic {
    position: absolute;
    top: 60px;
    right: -60px;
    width: 380px;
    height: 380px;
    opacity: 0.5;
  }

  .title-block {
    position: relative;
    z-index: 2;
    margin-top: 30px;
  }
  .title-main {
    color: #1e2f6e;
    font-size: 46px;
    line-height: 1.05;
    font-weight: normal;
  }
  .title-review {
    color: #1e2f6e;
    font-size: 26px;
    letter-spacing: 2px;
    font-weight: bold;
    margin-top: 6px;
  }

  .divider {
    border-top: 1px solid #9aa3c0;
    margin: 18px 0 18px 0;
    width: 100%;
  }

  .editor-in-chief {
    font-size: 12px;
    color: #333;
    margin-bottom: 6px;
  }
  .editor-name {
    font-size: 15px;
    color: #1e2f6e;
    font-weight: bold;
  }
  .editor-affil {
    font-size: 13px;
    color: #333;
    font-style: italic;
    font-weight: normal;
  }

  .spacer {
    flex-grow: 1;
    min-height: 260px;
  }

  .associate-editors {
    position: relative;
    z-index: 2;
    margin-top: 260px;
  }
  .ae-title {
    font-size: 12px;
    color: #333;
    margin-bottom: 6px;
  }
  .ae-list {
    font-size: 12.5px;
    line-height: 1.55;
  }
  .ae-name {
    color: #1e2f6e;
    font-weight: bold;
  }
  .ae-affil {
    font-style: italic;
    color: #333;
    font-weight: normal;
    font-size: 11.5px;
  }
</style>
</head>
